# -*- coding: utf-8 -*-
# (speaker, italiano, coreano); speaker None => didascalia, "#" => titolo di scena (nessuno dei due conta come battuta)
F, K, M, C, L, P = "Filippo", "Kim", "Matteo", "Chiara", "Lorenzo", "Park"
D = [
("#", "Scena 1 — Domenica 11 maggio, ore 8.30. La sala colazioni dell'albergo, Seul.", "장면 1 — 5월 11일 일요일 오전 8시 30분. 서울, 호텔 조식당."),
(None, "Filippo è sveglio dalle cinque: il fuso orario non perdona. Davanti a lui, un caffè americano che non beve e un foglio a quadretti pieno di numeri. Matteo arriva con due piatti, Chiara con una tazza di tè.", "필리포는 새벽 5시부터 깨어 있다. 시차는 봐주지 않는다. 그의 앞에는 마시지 않는 아메리카노 한 잔과 숫자로 가득 찬 모눈종이 한 장. 마테오는 접시 두 개를, 키아라는 찻잔 하나를 들고 온다."),
(M, "Hai dormito?", "잤어?"),
(F, "Tre ore. Il resto l'ho passato con questo foglio.", "세 시간. 나머지는 이 종이랑 보냈어."),
(C, "Fammi indovinare: il dazio.", "맞혀 볼게. 관세지."),
(F, "Il dazio. Giovedì Matteo ha avviato la pratica per l'esportatore autorizzato. Se ce la danno, il dazio sulle nostre borse in Corea passa dall'otto per cento a zero.", "관세. 목요일에 마테오가 인증수출자 신청을 시작했잖아. 그게 나오면 한국에서 우리 가방 관세가 8%에서 0%가 돼."),
(M, "E oggi la signora Kim ci chiederà che cosa vogliamo fare con quell'otto per cento.", "그리고 오늘 김 차장님이 그 8%를 어떻게 할 거냐고 물어보시겠지."),
(F, "Esatto. E io non ho ancora deciso.", "그래. 그런데 난 아직 결정을 못 했어."),
(C, "Io sì. Il prezzo in negozio non si tocca, a meno che i dati non dicano il contrario.", "난 했어. 매장 가격은 손대면 안 돼. 데이터가 반대로 말하지 않는 한."),
(F, "Lo sapevo che l'avresti detto. Ma spiegami perché, non dirmi solo che non ti piace.", "그렇게 말할 줄 알았어. 그래도 싫다고만 하지 말고 이유를 설명해 봐."),
(C, "Perché un prezzo che scende dopo un mese dice una cosa sola: che prima era sbagliato.", "한 달 만에 내려가는 가격은 딱 한 가지를 말하거든. 처음 가격이 틀렸다는 것."),
(M, "In Corea è ancora più vero. Al grande magazzino, se un marchio nuovo cala subito, la gente pensa che stia per sparire.", "한국에선 더 그래. 백화점에서 새 브랜드가 바로 가격을 내리면 사람들은 곧 없어질 브랜드라고 생각해."),
(F, "D'accordo. Ma la signora Kim deve vendere seicento borse il primo anno. Seicento, non sessanta. Se mi dice che a un milione e novanta ne vende il doppio?", "알았어. 하지만 김 차장님은 첫해에 600개를 팔아야 해. 60개가 아니라 600개. 109만 원이면 두 배를 판다고 하면?"),
(M, "Allora le chiediamo i dati. Non le opinioni, i dati.", "그럼 데이터를 달라고 하자. 의견 말고 데이터."),
(F, "Va bene. Ma a una condizione: oggi parlo io.", "좋아. 단 조건이 있어. 오늘은 내가 말할게."),
(M, "Tu? Di prezzi in coreano?", "형이? 한국어 가격 얘기를?"),
(F, "Di prezzi in euro. Il coreano lo lascio a te. Tu sei stato bravo con l'esclusiva, ma questa è la mia materia.", "유로 가격 얘기. 한국어는 너한테 맡길게. 너는 독점 건을 잘 해냈지만, 이건 내 분야야."),
(None, "Matteo apre la bocca, poi la richiude. Chiara gli passa sotto il tavolo un biscotto, come quando erano bambini.", "마테오가 입을 열었다가 다시 다문다. 키아라가 어릴 때처럼 탁자 밑으로 과자 하나를 건넨다."),
(C, "Lascialo fare, Matteo. È la prima volta che viene fin qui. Non rubargli la scena.", "하게 둬, 마테오. 형이 여기까지 온 건 처음이잖아. 형 무대를 뺏지 마."),
(M, "Va bene. Ma se sbagli una cifra, ti tiro un calcio.", "알았어. 근데 숫자 하나라도 틀리면 발로 찬다."),
(F, "Se sbaglio una cifra, me lo merito.", "숫자 틀리면 맞아도 싸지."),

("#", "Scena 2 — Ore 10. Ufficio della signora Kim, grande magazzino Gaon, sesto piano.", "장면 2 — 오전 10시. 가온백화점 6층, 김 차장 사무실."),
(None, "Dalla finestra si vede il traffico della domenica. La signora Kim ha davanti un tablet e una cartellina blu. Accanto a lei, Park Ji-hoon, il responsabile del pop-up, tiene in mano un quaderno pieno di appunti in coreano e in italiano.", "창밖으로 일요일의 차량 행렬이 보인다. 김 차장 앞에는 태블릿과 파란 서류철이 놓여 있다. 옆에는 팝업 매장 매니저 박지훈이 한국어와 이탈리아어로 메모가 빼곡한 공책을 들고 있다."),
(K, "Grazie di essere venuti di domenica. In Corea il grande magazzino la domenica lavora più di noi.", "일요일인데 와 주셔서 감사합니다. 한국에선 백화점이 일요일에 저희보다 더 일하거든요."),
(F, "Siamo noi a ringraziare Lei, signora Kim. E Le chiedo scusa: mio fratello mi dice che il mio italiano è troppo veloce. Se corro, mi fermi.", "감사는 저희가 드려야죠, 김 차장님. 그리고 미리 사과드릴게요. 동생 말로는 제 이탈리아어가 너무 빠르답니다. 제가 달리면 세워 주세요."),
(K, "Il Suo italiano va benissimo. È il mio che a volte fa le curve.", "이탈리아어 아주 좋으세요. 가끔 커브를 도는 건 제 이탈리아어고요."),
(F, "Allora andiamo dritti. Sappiamo tutti dell'esportatore autorizzato. Se arriva, l'otto per cento di dazio sparisce. Che cosa ne pensa?", "그럼 곧장 가죠. 인증수출자 얘기는 다 아시죠. 그게 나오면 관세 8%가 사라집니다. 어떻게 생각하세요?"),
(K, "Penso che sia una buona notizia per il cliente. Propongo di abbassare il prezzo della Scandicci da un milione centonovantamila a un milione novantamila won.", "고객에게 좋은 소식이라고 생각해요. 스칸디치 가격을 119만 원에서 109만 원으로 내리자고 제안합니다."),
(F, "Centomila won in meno. Mi spiega il ragionamento?", "10만 원 인하군요. 근거를 설명해 주시겠어요?"),
(K, "Sotto il milione e centomila c'è una soglia psicologica. Le clienti che oggi guardano e non comprano, a un milione e novanta comprerebbero.", "110만 원 아래에 심리적 경계선이 있어요. 오늘 보기만 하고 안 사는 손님들이 109만 원이면 살 거예요."),
(F, "Comprerebbero. È un condizionale. Lei ha dei numeri che lo dimostrano?", "'살 거예요'. 조건법이네요. 그걸 보여 주는 숫자가 있으세요?"),
(K, "Ho l'esperienza di altri marchi.", "다른 브랜드들의 경험이 있어요."),
(F, "Di altri marchi. E dei nostri? Signor Park, Lei è stato in negozio due settimane. Ci racconta?", "다른 브랜드들. 그럼 저희 브랜드는요? 박 매니저님, 2주 동안 매장에 계셨죠. 얘기해 주시겠어요?"),
(P, "Sì. Abbiamo venduto cinquantadue borse su sessantuno. La Domenica color crema è finita il terzo giorno.", "네. 61개 중 52개를 팔았습니다. 크림색 도메니카는 사흘째에 다 팔렸어요."),
(F, "E quante clienti hanno chiesto uno sconto?", "그럼 할인을 요구한 손님은 몇 명이었나요?"),
(P, "(sfoglia il quaderno) Due. Una era una signora che chiede sempre lo sconto, anche per il caffè.", "(공책을 넘기며) 두 명이요. 한 분은 커피값도 깎는 분이었어요."),
(C, "(ride piano) Ne abbiamo una uguale a Scandicci.", "(작게 웃으며) 스칸디치에도 똑같은 분이 한 분 계세요."),
(P, "Le altre chiedevano chi aveva cucito la borsa. Leggevano il cartellino scritto a mano.", "다른 손님들은 누가 그 가방을 꿰맸는지 물었어요. 손글씨 택을 읽더라고요."),
(K, "Ji-hoon, grazie. Ma il pop-up non è il negozio fisso. Al pop-up vengono le curiose. Per seicento borse servono le clienti normali.", "지훈 씨, 고마워요. 하지만 팝업은 상설 매장이 아니에요. 팝업에는 호기심 많은 손님이 와요. 600개를 팔려면 평범한 손님이 필요해요."),
(F, "Ha ragione. Il pop-up non è una prova definitiva. Ma neanche l'esperienza di altri marchi lo è.", "맞습니다. 팝업은 확정적인 증거가 아니죠. 하지만 다른 브랜드의 경험도 그렇진 않습니다."),
(K, "E allora come decidiamo, signor Corsini?", "그럼 어떻게 결정하죠, 코르시니 사장님?"),
(F, "Le dico come la vedo io. Se il prezzo scende a un mese dal lancio, chi ha comprato a un milione e centonovanta si sente preso in giro. E sono proprio le clienti che porteranno le amiche.", "제 생각을 말씀드리죠. 출시 한 달 만에 가격이 내려가면 119만 원에 산 분들은 속았다고 느낄 겁니다. 그런데 친구를 데려올 사람이 바로 그분들이에요."),
(C, "Sua sorella, sua collega, sua madre. Da noi funziona così.", "자매, 동료, 어머니. 저희 쪽에선 그렇게 돌아가요."),
(K, "Anche da noi. Ma da noi funziona anche la parola « nuovo prezzo ».", "저희도 그래요. 하지만 저희는 '새 가격'이라는 말도 잘 통해요."),
(M, "Posso? Una cosa sola.", "제가 한마디만 해도 될까요? 딱 하나만."),
(F, "(lo guarda, poi annuisce) Una sola.", "(동생을 보다가 고개를 끄덕이며) 딱 하나."),
(M, "Signora Kim, quando lavoravo al grande magazzino, il marchio che abbassava il prezzo dopo il lancio era sempre il primo a essere spostato al secondo piano. Non avrebbe dovuto farlo.", "김 차장님, 제가 백화점에서 일할 때, 출시 후에 가격을 내린 브랜드는 늘 제일 먼저 2층으로 밀려났어요. 그러지 말았어야 했죠."),
(K, "(sorride appena) Lo so. Ero io a spostarli.", "(살짝 웃으며) 알아요. 옮긴 사람이 저였으니까요."),
(None, "Un silenzio breve. Park abbassa lo sguardo sul quaderno per non ridere.", "짧은 침묵. 박지훈은 웃음을 참으려고 공책으로 눈을 내린다."),
(C, "Signora Kim, posso farLe io una domanda?", "김 차장님, 제가 하나 여쭤봐도 될까요?"),
(K, "Prego.", "그러세요."),
(C, "Le clienti che hanno comprato la Domenica color crema: Lei le ha viste tornare?", "크림색 도메니카를 산 손님들, 다시 오는 거 보셨어요?"),
(K, "Tre sono tornate con un'amica. Una con la figlia.", "세 분은 친구랑 다시 왔어요. 한 분은 딸이랑요."),
(C, "Allora il nostro prezzo ha già lavorato per noi.", "그럼 저희 가격이 벌써 저희를 위해 일한 거네요."),
(K, "Oppure la novità. A Seul le novità durano poco.", "아니면 새로움이 일했거나요. 서울에선 새로움이 오래가지 않아요."),
(M, "Per questo servono novità vere, non sconti.", "그래서 할인이 아니라 진짜 새로움이 필요한 거죠."),
(F, "Allora facciamo così. Prima di decidere il prezzo, guardiamo quanto vale davvero quell'otto per cento. Alle quattro ho una videochiamata con il nostro direttore amministrativo. Possiamo rivederci alle sei e mezza?", "그럼 이렇게 하죠. 가격을 정하기 전에 그 8%가 실제로 얼마인지 보죠. 4시에 저희 관리 책임자와 화상 통화가 있습니다. 6시 반에 다시 뵐 수 있을까요?"),
(K, "Alle sei e mezza. Ma signor Corsini, domani si firma. Il contratto ha bisogno di un prezzo.", "6시 반이요. 그런데 코르시니 사장님, 내일 서명이에요. 계약서에는 가격이 있어야 해요."),
(F, "Lo avrà. Glielo prometto.", "있을 겁니다. 약속드리죠."),

("#", "Scena 3 — Ore 16. Una saletta dell'albergo. In Italia sono le nove del mattino.", "장면 3 — 오후 4시. 호텔의 작은 회의실. 이탈리아는 오전 9시."),
(None, "Sullo schermo del portatile compare Lorenzo, nell'ufficio di Scandicci, con la giacca di domenica e una tazzina in mano. Dietro di lui, la finestra sul cortile del laboratorio.", "노트북 화면에 스칸디치 사무실의 로렌초가 일요일용 재킷을 입고 에스프레소 잔을 든 채 나타난다. 그의 뒤로 공방 마당 쪽 창문이 보인다."),
(L, "Buongiorno, o buonasera, non so più. Ho fatto i conti che mi avete chiesto.", "좋은 아침, 아니 좋은 저녁인가. 이제 모르겠네요. 부탁하신 계산 해 놨습니다."),
(F, "Vai, Lorenzo. Senza giri.", "말해, 로렌초. 돌리지 말고."),
(L, "La Scandicci parte da noi a trecentotrenta euro. In negozio, a Seul, oggi ci arriva a circa quattrocentosessantacinque euro, contando aereo, dazio, IVA coreana e costi locali. Senza dazio scende a circa quattrocentotrentaquattro, perché l'IVA coreana si calcola anche sul dazio.", "스칸디치는 저희 공장에서 330유로로 나갑니다. 지금 서울 매장 도착 원가는 항공, 관세, 한국 부가세, 현지 비용까지 약 465유로예요. 관세가 없으면 약 434유로로 내려가요. 한국 부가세가 관세까지 포함해서 계산되니까요."),
(M, "Quindi senza dazio si risparmia anche un po' di IVA.", "그러니까 관세가 없으면 부가세도 조금 아끼는 거네."),
(L, "Esatto. In tutto, circa trentuno euro a borsa. Sulle seicento borse del minimo fa circa diciottomilanovecento euro l'anno.", "맞아요. 다 합치면 가방 하나에 약 31유로. 최소 물량 600개면 1년에 약 1만 8,900유로예요."),
(C, "Quasi diciannovemila euro. Più di quello che è costata la nostra fiera.", "거의 1만 9천 유로. 우리 박람회 비용보다 많네."),
(F, "E chi se li prende, questi diciannovemila? Questa è la vera domanda.", "그럼 그 1만 9천 유로는 누가 가져가지? 이게 진짜 질문이야."),
(L, "Oggi il dazio lo paga il grande magazzino, perché compra franco fabbrica. Quindi, se non facciamo niente, il risparmio è tutto loro.", "지금은 백화점이 공장 인도 조건으로 사니까 관세도 그쪽이 내요. 그러니 우리가 아무것도 안 하면 절감분은 전부 그쪽 거예요."),
(M, "E lei lo vuole usare per abbassare il prezzo.", "그리고 김 차장님은 그걸 가격 내리는 데 쓰고 싶어 하고."),
(F, "E noi vogliamo che il prezzo resti dov'è. Allora quei soldi devono andare da qualche altra parte.", "그리고 우리는 가격이 그대로 있길 원하지. 그럼 그 돈은 다른 데로 가야 해."),
(L, "Posso fare una proposta da ragioniere?", "회계 담당자다운 제안 하나 해도 될까요?"),
(F, "Le uniche che mi fido ad ascoltare.", "내가 믿고 듣는 건 그런 제안뿐이야."),
(L, "Dividiamo. Noi alziamo il prezzo franco fabbrica per la Corea di quindici euro: la Scandicci passa da trecentotrenta a trecentoquarantacinque. Il resto, circa sedici euro a borsa, resta al grande magazzino.", "나누는 겁니다. 한국용 공장 출고가를 15유로 올려요. 스칸디치는 330에서 345유로가 되죠. 나머지 가방당 약 16유로는 백화점이 가져가고요."),
(M, "E il prezzo in negozio non cambia. La cliente non vede niente.", "그리고 매장 가격은 그대로. 손님은 아무것도 못 느끼고."),
(C, "Ma il grande magazzino perché dovrebbe accettare? Perde quindici euro che oggi pensa già suoi.", "근데 백화점이 왜 받아들이겠어? 이미 자기 거라고 생각하는 15유로를 잃는 건데."),
(F, "Perché con quei quindici euro facciamo qualcosa che serve anche a lei.", "그 15유로로 그쪽에도 도움이 되는 걸 할 거니까."),
(M, "Nuovi modelli.", "새 모델."),
(F, "Nuovi modelli. Chiara, quanti ne puoi preparare per l'autunno, senza tradire la qualità?", "새 모델. 키아라, 품질을 배신하지 않고 가을까지 몇 개 준비할 수 있어?"),
(C, "Tre. Non uno di più. La Collina, che a Seul ha già diciotto ordini. La Badia, per chi vuole una borsa grande. E la Ponte, la piccola a tracolla che Kim mi ha chiesto il secondo giorno.", "세 개. 하나도 더는 안 돼. 서울에서 벌써 주문이 18건인 라 콜리나. 큰 가방 원하는 사람용 바디아. 그리고 김 차장님이 둘째 날 부탁한 작은 크로스백 폰테."),
(M, "La Ponte? Non è nel campionario.", "폰테? 그건 샘플 컬렉션에 없잖아."),
(C, "Non ancora. L'ho disegnata in aereo, tra una caramella allo zenzero e l'altra.", "아직은. 비행기에서 그렸어. 생강 사탕 사이사이에."),
(F, "Quanto tempo per un prototipo?", "시제품 하나에 얼마나 걸려?"),
(C, "Tre settimane, se Renzo non ha altro. Ma a giugno ha la Maison.", "렌초가 다른 일이 없으면 3주. 근데 6월엔 메종 일이 있어."),
(L, "La Maison consegna a fine giugno. Da luglio Renzo è vostro.", "메종 납품이 6월 말이에요. 7월부턴 렌초는 여러분 거예요."),
(C, "Allora prototipi a luglio, produzione ad agosto. Stretto, ma si può.", "그럼 시제품은 7월, 생산은 8월. 빠듯하지만 할 수 있어."),
(L, "Tre modelli nuovi significano campioni, cartamodelli, tempo di Renzo. Con quei quindici euro a borsa ci stiamo dentro. Senza, sarebbe dura.", "새 모델 세 개면 샘플, 패턴, 렌초의 시간이 들어요. 가방당 15유로면 감당할 수 있어요. 그게 없으면 힘들고요."),
(F, "Lorenzo, e il tetto dei centocinquantamila?", "로렌초, 15만 유로 상한은?"),
(L, "Non lo tocchiamo. I nuovi modelli si pagano con la differenza di prezzo, non con il budget del marchio.", "건드리지 않아요. 새 모델은 가격 차이로 감당하지, 브랜드 예산으로 하는 게 아니에요."),
(F, "Perfetto. Ultima cosa: e se l'esportatore autorizzato non arriva?", "완벽해. 마지막으로, 인증수출자가 안 나오면?"),
(L, "Allora non c'è niente da dividere e i prezzi restano quelli di oggi. Basta scriverlo nel contratto: l'aumento scatta solo dal giorno in cui il dazio è zero.", "그럼 나눌 것도 없고 가격은 지금 그대로죠. 계약서에 쓰기만 하면 돼요. 인상은 관세가 0이 되는 날부터만 적용된다고."),
(M, "Lorenzo, sei un genio.", "로렌초, 당신 천재야."),
(L, "No, sono uno che lavora con tuo padre dal novantasei. Lui diceva sempre: « Il prezzo al pubblico è del cliente. Il margine è nostro. »", "아니요, 1996년부터 당신 아버지랑 일한 사람일 뿐이에요. 그분이 늘 그러셨죠. '소비자 가격은 손님 것이다. 마진은 우리 것이다.'"),
(None, "Filippo guarda il foglio a quadretti. Accanto all'ultima riga scrive, in piccolo: « 345 — Collina, Badia, Ponte ».", "필리포가 모눈종이를 본다. 마지막 줄 옆에 작게 적는다. '345 — 콜리나, 바디아, 폰테'."),

("#", "Scena 4 — Ore 18.30. Di nuovo al sesto piano del grande magazzino Gaon.", "장면 4 — 오후 6시 30분. 다시 가온백화점 6층."),
(F, "Signora Kim, abbiamo una proposta. Mi permetta di presentarla in tre punti.", "김 차장님, 제안이 있습니다. 세 가지로 말씀드려도 될까요?"),
(K, "Prego.", "말씀하세요."),
(F, "Primo: il prezzo al pubblico resta un milione centonovantamila won. Né oggi né in autunno.", "첫째, 소비자 가격은 119만 원으로 유지합니다. 오늘도, 가을에도."),
(K, "Secondo?", "둘째는요?"),
(F, "Secondo: dal giorno in cui il dazio sarà zero, e solo da quel giorno, il nostro prezzo franco fabbrica per la Corea sale del quattro e mezzo per cento. La Scandicci passa a trecentoquarantacinque euro. Del risparmio sul dazio, circa metà resta a voi.", "둘째, 관세가 0이 되는 날부터, 오직 그날부터만 한국용 공장 출고가를 4.5% 올립니다. 스칸디치는 345유로가 됩니다. 관세 절감분의 절반 정도는 귀사에 남습니다."),
(K, "Metà. E con l'altra metà che cosa fate?", "절반이요. 그럼 나머지 절반으로는 뭘 하시죠?"),
(F, "Terzo punto: tre modelli nuovi per l'autunno, solo per la Corea nei primi sei mesi. La Collina, la Badia e la Ponte.", "셋째, 가을용 새 모델 세 개를 처음 6개월은 한국에만 냅니다. 라 콜리나, 바디아, 폰테."),
(K, "(guarda Chiara) La Ponte? La piccola che Le ho chiesto?", "(키아라를 보며) 폰테요? 제가 부탁드린 그 작은 거요?"),
(C, "Quella. Con la tracolla regolabile, come voleva Lei. E più leggera di cento grammi.", "그거요. 원하신 대로 끈 길이를 조절할 수 있게요. 그리고 100그램 더 가볍게요."),
(K, "Signor Corsini, Lei capisce che mi sta chiedendo di rinunciare a un prezzo più basso, che piace al mio direttore.", "코르시니 사장님, 저희 상무님이 좋아하실 더 낮은 가격을 포기하라고 하시는 거, 아시죠?"),
(F, "Capisco. Le sto chiedendo di scambiare centomila won di sconto con tre ragioni in più per entrare in negozio.", "압니다. 10만 원 할인을, 매장에 들어올 이유 세 가지와 바꾸자고 말씀드리는 겁니다."),
(K, "Tre ragioni in più... Questa frase la posso usare con il mio direttore?", "들어올 이유 세 가지라… 이 말 저희 상무님께 써도 될까요?"),
(F, "È Sua. Gliela regalo.", "차장님 거예요. 선물로 드리죠."),
(P, "Signora Kim, posso dire una cosa? Le clienti mi chiedevano ogni giorno quando sarebbero arrivati i modelli nuovi.", "차장님, 하나 말씀드려도 될까요? 손님들이 새 모델은 언제 오냐고 매일 물었어요."),
(K, "(sospira, poi sorride) Va bene. Accetto a due condizioni.", "(한숨을 쉬고 나서 웃으며) 좋아요. 두 가지 조건으로 받아들이죠."),
(F, "Mi dica.", "말씀하세요."),
(K, "Prima: i tre modelli arrivano a Seul entro il quindici settembre, non un giorno dopo. La stagione autunnale da noi comincia presto.", "첫째, 세 모델은 9월 15일까지 서울에 도착해야 해요. 하루도 늦으면 안 돼요. 저희 가을 시즌은 일찍 시작하거든요."),
(C, "Il quindici settembre. Si può fare, se Renzo comincia a luglio e non dorme ad agosto.", "9월 15일. 렌초가 7월에 시작해서 8월에 잠을 안 자면 가능해요."),
(K, "Seconda: un colore solo per noi. Uno che nessun altro negozio al mondo avrà per un anno.", "둘째, 저희만의 색 하나. 1년 동안 세상 어느 매장에도 없는 색이요."),
(C, "Un colore... (pensa) Il grigio del cielo di Seul la mattina. Non grigio, quasi azzurro.", "색이라… (생각하며) 아침 서울 하늘의 회색. 회색이 아니라 거의 하늘색에 가까운."),
(K, "(ride) Il cielo di Seul la mattina è soprattutto smog.", "(웃으며) 아침 서울 하늘은 대부분 미세먼지예요."),
(C, "Allora lo chiamerò « dopo la pioggia ».", "그럼 '비 온 뒤'라고 부를게요."),
(M, "Signora Kim, tutto questo va scritto nel contratto di domani?", "김 차장님, 이걸 다 내일 계약서에 넣어야 하나요?"),
(K, "Nel contratto mettiamo il prezzo e la clausola del dazio. I modelli e il colore in un allegato. Il direttore Han preferisce i contratti corti.", "계약서에는 가격과 관세 조항만 넣어요. 모델과 색은 부속서로. 한 상무님은 짧은 계약서를 좋아하세요."),
(F, "Anche mia madre. Dice che i contratti lunghi servono a chi non si fida.", "저희 어머니도 그래요. 긴 계약서는 서로 못 믿는 사람들이 쓰는 거라고 하시죠."),
(K, "Allora sua madre e il direttore Han andrebbero d'accordo.", "그럼 어머님과 한 상무님은 잘 맞으시겠네요."),
(F, "Speriamo che non si incontrino mai. Insieme comanderebbero il mondo.", "두 분이 절대 안 만나시길 바랍시다. 같이 계시면 세상을 지배하실 거예요."),
(K, "(ride, poi si alza) Domani alle undici, al dodicesimo piano, con il direttore Han. E, signor Corsini, porti una penna.", "(웃다가 일어서며) 내일 11시, 12층에서 한 상무님과 함께요. 그리고 코르시니 사장님, 펜 가져오세요."),
(F, "Ce l'ho. È quella di mio padre.", "있습니다. 아버지 펜이에요."),
(None, "In ascensore, i tre fratelli scendono in silenzio fino al piano terra. Poi Matteo dà una spallata a Filippo.", "엘리베이터에서 삼남매는 1층까지 말없이 내려간다. 그러다 마테오가 필리포를 어깨로 툭 친다."),
(M, "Non hai sbagliato una cifra.", "숫자 하나도 안 틀렸네."),
(F, "Lo so. Il calcio te lo tieni.", "알아. 발차기는 넣어 둬."),
(C, "« Tre ragioni in più per entrare in negozio. » Dove l'hai imparata?", "'매장에 들어올 이유 세 가지'. 그런 말은 어디서 배웠어?"),
(F, "Da una signora che il sabato va a vendere borse a Milano.", "토요일마다 밀라노에 가방 팔러 가는 어떤 부인한테서."),
(M, "La mamma.", "엄마."),
(F, "La mamma. Ma non diteglielo. Si monta la testa.", "엄마. 근데 엄마한텐 말하지 마. 우쭐해하실 거야."),
]

